(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0RD_1LC0RB_0LC1RD_0LA0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB0RD_1LC0RB_0LC1RD_0LA0RB /\
  lift (cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0RD_1LC0RB_0LC1RD_0LA0RB) = lift (Cc (Pos.succ p)).
