Lemma geo_1RB0RD_1LC0RB_0LC1RD_0LA1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RD_1LC0RB_0LC1RD_0LA1LA) = lift (Cc (Pos.succ p)).
