      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 4]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0RD_1LC0RD_1LA1LB_0LC1RD : NeverQuasiHaltsTr tm_1RB0RD_1LC0RD_1LA1LB_0LC1RD.
Proof.
  apply (glue_neverqhtr tm_1RB0RD_1LC0RD_1LA1LB_0LC1RD pins_1RB0RD_1LC0RD_1LA1LB_0LC1RD Cc 6).
