  intros p j q0 E.
  exists (6 * j + 10), (cden (Kp q0 ++ [S0]) [] j A1_1RB0RD_1LC1LA_1RD0LC_0RB0LA).
  split; [lia|]. split; [| exact (gei_1RB0RD_1LC1LA_1RD0LC_0RB0LA p j q0 E)].
  rewrite (gsi_1RB0RD_1LC1LA_1RD0LC_0RB0LA p j q0 E).
  exact (srun_sound tm false true chi_1RB0RD_1LC1LA_1RD0LC_0RB0LA A0_1RB0RD_1LC1LA_1RD0LC_0RB0LA A1_1RB0RD_1LC1LA_1RD0LC_0RB0LA 6 10
           run_int_1RB0RD_1LC1LA_1RD0LC_0RB0LA (Kp q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0RD_1LC1LA_1RD0LC_0RB0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RD_1LC1LA_1RD0LC_0RB0LA.
