Lemma lbl_1RB0RD_1LC1LA_1RD0LC_0RB0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RD_1LC1LA_1RD0LC_0RB0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RD_1LC1LA_1RD0LC_0RB0LA) = lift (Cc (Pos.succ p)).
