Lemma run_inner_1RB0RD_1LC1LB_0RA0LB_1LB1RA : srun tm false true chn_1RB0RD_1LC1LB_0RA0LB_1LB1RA AI0_1RB0RD_1LC1LB_0RA0LB_1LB1RA = Some (AI1_1RB0RD_1LC1LB_0RA0LB_1LB1RA, 4, 4).
