Lemma lapin_1RB0RD_1LC1LB_0RA0LB_1LB1RA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S1;S1;S1]) [] i AI1_1RB0RD_1LC1LB_0RA0LB_1LB1RA).
  split; [lia|]. split; [| exact (gen_1RB0RD_1LC1LB_0RA0LB_1LB1RA v i q0 E)].
  rewrite (gsn_1RB0RD_1LC1LB_0RA0LB_1LB1RA v i q0 E).
  exact (srun_sound tm false true chn_1RB0RD_1LC1LB_0RA0LB_1LB1RA AI0_1RB0RD_1LC1LB_0RA0LB_1LB1RA AI1_1RB0RD_1LC1LB_0RA0LB_1LB1RA 4 4
           run_inner_1RB0RD_1LC1LB_0RA0LB_1LB1RA (Ip q0 ++ [S1;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB0RD_1LC1LB_0RA0LB_1LB1RA : forall j, lift (cden [] [] j BB1_1RB0RD_1LC1LB_0RA0LB_1LB1RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0RD_1LC1LB_0RA0LB_1LB1RA = (StC, ((rep [S1;S0] j ++ [S1;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB0RD_1LC1LB_0RA0LB_1LB1RA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0] j ++ [S1;S1;S1;S1], S0, []))).
  { unfold Cin_1RB0RD_1LC1LB_0RA0LB_1LB1RA. rewrite epow2_1RB0RD_1LC1LB_0RA0LB_1LB1RA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0RD_1LC1LB_0RA0LB_1LB1RA. rewrite ?lift_app_blank. reflexivity.
