  apply (nested_overflow_lift tm Cc Cin lapin_1RB0RD_1LC1LB_0RA0LC_1RA0LB p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_1RB0RD_1LC1LB_0RA0LC_1RA0LB).
    split; [lia|]. split; [| exact (gbo_1RB0RD_1LC1LB_0RA0LC_1RA0LB j)].
    rewrite (gso_1RB0RD_1LC1LB_0RA0LC_1RA0LB p j E).
    exact (srun_sound tm true true chb_1RB0RD_1LC1LB_0RA0LC_1RA0LB B0_1RB0RD_1LC1LB_0RA0LC_1RA0LB BB1_1RB0RD_1LC1LB_0RA0LC_1RA0LB 8 4
             run_boot_1RB0RD_1LC1LB_0RA0LC_1RA0LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 16), (cden [] [] j B1_1RB0RD_1LC1LB_0RA0LC_1RA0LB).
    split; [| exact (geo_1RB0RD_1LC1LB_0RA0LC_1RA0LB p j E)].
