  apply (fire_of_run_instr tm Cc true true l B0_1RB0RD_1LC1LB_0RA0LC_1RA0LB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RD_1LC1LB_0RA0LC_1RA0LB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0RD_1LC1LB_0RA0LC_1RA0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0RD_1LC1LB_0RA0LC_1RA0LB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0RD_1LC1LB_0RA0LC_1RA0LB t p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_1RB0RD_1LC1LB_0RA0LC_1RA0LB). split;
      [| exact (gbo_1RB0RD_1LC1LB_0RA0LC_1RA0LB j)].
