      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RD_1LC1LB_0RA1LB_1RA0LB (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0RD_1LC1LB_0RA1LB_1RA0LB [SRotL 1; SWin 1; SCycL 2 0; SWinL 5] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RD_1LC1LB_0RA1LB_1RA0LB
      with (l := []).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0RD_1LC1LB_0RA1LB_1RA0LB (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB0RD_1LC1LB_0RA1LB_1RA0LB [SRotL 1; SWin 1; SCycL 2 0; SWinL 4] (StC, S1) ltac:(vm_compute; reflexivity)
