(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0RD_1LC1LB_1RA0LC_0LB0RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z0_1RB0RD_1LC1LB_1RA0LC_0LB0RD /\
  lift (cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z1_1RB0RD_1LC1LB_1RA0LC_0LB0RD) = lift (Cc (Pos.succ p)).
Proof.
