Lemma gsi_1RB0RD_1LC1RA_0RB0LD_0LB0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_01_1 q0 ++ [S0]) [] j A0_1RB0RD_1LC1RA_0RB0LD_0LB0LC.
