                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0RD_1LC1RA_0RB0LD_0LB0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB0RD_1LC1RA_0RB0LD_0LB0LC (StA, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB0RD_1LC1RA_0RB0LD_0LB0LC [SWinR 2; SCycL 2 0; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
