  split; [lia|]. split; [| exact (gei_1RB0RD_1LC1RB_0RA1LD_1LB0LC p j q0 E)].
  rewrite (gsi_1RB0RD_1LC1RB_0RA1LD_1LB0LC p j q0 E).
