Lemma gei_1RB0RD_1LC1RB_0RB1LA_0LC1LD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0RD_1LC1RB_0RB1LA_0LC1LD) = lift (Cc (Pos.succ p)).
Proof.
