(** ** Bootstrap *)

Lemma boot_1RB1LA_0LA1RC_0LA0LD_0RB1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 5.
  assert (H : match csteps tm 5 c0 with
