                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 4), (cden [] [] j BB1_1RB1LA_0LA1RC_0LA1RD_0LB0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LA1RC_0LA1RD_0LB0RB j)].
