    exact (srun_sound tm true true chm_1RB1LA_0LA1RC_0LA1RD_0LB0RB BM0_1RB1LA_0LA1RC_0LA1RD_0LB0RB BM1_1RB1LA_0LA1RC_0LA1RD_0LB0RB 6 6
             run_shift_1RB1LA_0LA1RC_0LA1RD_0LB0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
