Lemma lapi_1RB1LA_0LA1RC_0LA1RD_0LD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LA_0LA1RC_0LA1RD_0LD0RB p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LA_0LA1RC_0LA1RD_0LD0RB Z0_1RB1LA_0LA1RC_0LA1RD_0LD0RB Z1_1RB1LA_0LA1RC_0LA1RD_0LD0RB 0 2
               run_z_1RB1LA_0LA1RC_0LA1RD_0LD0RB (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
