(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0LA1RC_0LA1RD_0LD0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1LA_0LA1RC_0LA1RD_0LD0RB p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 4), (cden [] [] j BB1_1RB1LA_0LA1RC_0LA1RD_0LD0RB).
      split; [lia|]. split; [| exact (gbo_1RB1LA_0LA1RC_0LA1RD_0LD0RB j)].
      rewrite (gso_1RB1LA_0LA1RC_0LA1RD_0LD0RB p j E).
      exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0LA1RD_0LD0RB B0_1RB1LA_0LA1RC_0LA1RD_0LD0RB BB1_1RB1LA_0LA1RC_0LA1RD_0LD0RB 6 4
               run_boot_1RB1LA_0LA1RC_0LA1RD_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LA_0LA1RC_0LA1RD_0LD0RB p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (6 * j + 6), (cden [] [] j BM1_1RB1LA_0LA1RC_0LA1RD_0LD0RB).
      split; [| exact (gbo2_1RB1LA_0LA1RC_0LA1RD_0LD0RB j)].
      rewrite (gxi_1RB1LA_0LA1RC_0LA1RD_0LD0RB j).
      exact (srun_sound tm true true chm_1RB1LA_0LA1RC_0LA1RD_0LD0RB BM0_1RB1LA_0LA1RC_0LA1RD_0LD0RB BM1_1RB1LA_0LA1RC_0LA1RD_0LD0RB 6 6
               run_shift_1RB1LA_0LA1RC_0LA1RD_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (6 * j + 12), (cden [] [] j B1_1RB1LA_0LA1RC_0LA1RD_0LD0RB).
    split; [| exact (geo_1RB1LA_0LA1RC_0LA1RD_0LD0RB p j E)].
    rewrite (gxi2_1RB1LA_0LA1RC_0LA1RD_0LD0RB j).
    exact (srun_sound tm true true che_1RB1LA_0LA1RC_0LA1RD_0LD0RB BE0_1RB1LA_0LA1RC_0LA1RD_0LD0RB B1_1RB1LA_0LA1RC_0LA1RD_0LD0RB 6 12
             run_exit_1RB1LA_0LA1RC_0LA1RD_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma visx_1RB1LA_0LA1RC_0LA1RD_0LD0RB : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LA_0LA1RC_0LA1RD_0LD0RB = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 4), (cden [] [] j BB1_1RB1LA_0LA1RC_0LA1RD_0LD0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LA1RC_0LA1RD_0LD0RB j)].
    rewrite (gso_1RB1LA_0LA1RC_0LA1RD_0LD0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0LA1RD_0LD0RB B0_1RB1LA_0LA1RC_0LA1RD_0LD0RB BB1_1RB1LA_0LA1RC_0LA1RD_0LD0RB 6 4
             run_boot_1RB1LA_0LA1RC_0LA1RD_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LA_0LA1RC_0LA1RD_0LD0RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 6), (cden [] [] j BM1_1RB1LA_0LA1RC_0LA1RD_0LD0RB).
    split; [| exact (gbo2_1RB1LA_0LA1RC_0LA1RD_0LD0RB j)].
    rewrite (gxi_1RB1LA_0LA1RC_0LA1RD_0LD0RB j).
    exact (srun_sound tm true true chm_1RB1LA_0LA1RC_0LA1RD_0LD0RB BM0_1RB1LA_0LA1RC_0LA1RD_0LD0RB BM1_1RB1LA_0LA1RC_0LA1RD_0LD0RB 6 6
             run_shift_1RB1LA_0LA1RC_0LA1RD_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (vis_via_fill tm Cc Cin2 lapin2_1RB1LA_0LA1RC_0LA1RD_0LD0RB q p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (vis_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (vis_of_run tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_1RB1LA_0LA1RC_0LA1RD_0LD0RB xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_1RB1LA_0LA1RC_0LA1RD_0LD0RB j)].
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_0LA1RC_0LA1RD_0LD0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0LA1RC_0LA1RD_0LD0RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0LA1RC_0LA1RD_0LD0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LA1RC_0LA1RD_0LD0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 1.
  assert (H : match csteps tm 1 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 1 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LA1RC_0LA1RD_0LD0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LA1RC_0LA1RD_0LD0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LA1RC_0LA1RD_0LD0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LA1RC_0LA1RD_0LD0RB p j E)].
