  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LA1RC_0LA1RD_0RC0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LA1RC_0LA1RD_0RC0RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LA_0LA1RC_0LA1RD_0RC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LA_0LA1RC_0LA1RD_0RC0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LA_0LA1RC_0LA1RD_0RC0RB t p (pow2 j)).
  - exists (6 * j + 8), (cden [] [] j BB1_1RB1LA_0LA1RC_0LA1RD_0RC0RB). split;
      [| exact (gbo_1RB1LA_0LA1RC_0LA1RD_0RC0RB j)].
    rewrite (gso_1RB1LA_0LA1RC_0LA1RD_0RC0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0LA1RD_0RC0RB B0_1RB1LA_0LA1RC_0LA1RD_0RC0RB BB1_1RB1LA_0LA1RC_0LA1RD_0RC0RB 6 8
             run_boot_1RB1LA_0LA1RC_0LA1RD_0RC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LA_0LA1RC_0LA1RD_0RC0RB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LA_0LA1RC_0LA1RD_0RC0RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LA1RC_0LA1RD_0RC0RB : forall t, ~ In t pins_1RB1LA_0LA1RC_0LA1RD_0RC0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0LA1RC_0LA1RD_0RC0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_0LA1RC_0LA1RD_0RC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0LA1RC_0LA1RD_0RC0RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_0LA1RC_0LA1RD_0RC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SWinR 2; SUnrotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_0LA1RC_0LA1RD_0RC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_0LA1RC_0LA1RD_0RC0RB
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0LA1RC_0LA1RD_0RC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LA_0LA1RC_0LA1RD_0RC0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LA_0LA1RC_0LA1RD_0RC0RB (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LA_0LA1RC_0LA1RD_0RC0RB [SWinR 2; SCycL 3 0; SWin 3; SWinL 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LA1RC_0LA1RD_0RC0RB : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_0LA1RD_0RC0RB.
Proof.
