    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LA0RB [SWin 1; SWinR 3; SCycL 3 0; SWin 8; SCycR 3; SWin 4; SRotL 1; SWin 1; SWinR 4] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LA0RB [SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
