    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LA0RB [SWin 1; SWinR 3; SCycL 3 0; SWin 6] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LA0RB [SWin 1; SWinR 3; SCycL 3 0; SWin 8; SCycR 3; SWin 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LA0RB [SWin 1; SWinR 3; SCycL 3 0; SWin 7] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
