    rewrite (srun_sound tm false true chz_1RB1LA_0LA1RC_0LA1RD_1LC0RB Z0_1RB1LA_0LA1RC_0LA1RD_1LC0RB Z1_1RB1LA_0LA1RC_0LA1RD_1LC0RB 0 2
