Definition chb_1RB1LA_0LA1RC_0LA1RD_1LD0RB : list lstep := [SWin 1; SWinR 3; SCycL 3 0; SWin 8; SCycR 3; SWin 4; SWinR 8; SRotL 1; SWin 1].

Lemma run_boot_1RB1LA_0LA1RC_0LA1RD_1LD0RB : srun tm true true chb_1RB1LA_0LA1RC_0LA1RD_1LD0RB B0_1RB1LA_0LA1RC_0LA1RD_1LD0RB = Some (BB1_1RB1LA_0LA1RC_0LA1RD_1LD0RB, 6, 25).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_0LA1RC_0LA1RD_1LD0RB : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [S1;S1;S1] [] 0 0 []).
Definition che_1RB1LA_0LA1RC_0LA1RD_1LD0RB : list lstep := [SWin 3; SWinR 7; SCycL 3 0; SWin 3; SWinL 5; SCycR 3; SWin 6; SRotL 1; SFoldL 1].

Lemma run_exit_1RB1LA_0LA1RC_0LA1RD_1LD0RB : srun tm true true che_1RB1LA_0LA1RC_0LA1RD_1LD0RB BE0_1RB1LA_0LA1RC_0LA1RD_1LD0RB = Some (B1_1RB1LA_0LA1RC_0LA1RD_1LD0RB, 6, 24).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
Proof.
  intros p j q0 E. destruct (Alph_110_111_111.cview_some_Alph_110_111_111 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LA_0LA1RC_0LA1RD_1LD0RB, cden, A0_1RB1LA_0LA1RC_0LA1RD_1LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S0] where the anchor has [S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A1_1RB1LA_0LA1RC_0LA1RD_1LD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_110_111_111.cview_some_Alph_110_111_111 p j q0 E) as (_ & H2).
  unfold Cc_1RB1LA_0LA1RC_0LA1RD_1LD0RB, cden, A1_1RB1LA_0LA1RC_0LA1RD_1LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0]) with (([S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 14), (cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A1_1RB1LA_0LA1RC_0LA1RD_1LD0RB).
  split; [lia|]. split; [| exact (gei_1RB1LA_0LA1RC_0LA1RD_1LD0RB p j q0 E)].
  rewrite (gsi_1RB1LA_0LA1RC_0LA1RD_1LD0RB p j q0 E).
  exact (srun_sound tm false true chi_1RB1LA_0LA1RC_0LA1RD_1LD0RB A0_1RB1LA_0LA1RC_0LA1RD_1LD0RB A1_1RB1LA_0LA1RC_0LA1RD_1LD0RB 6 14
           run_int_1RB1LA_0LA1RC_0LA1RD_1LD0RB (Ap_Alph_110_111_111 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
Proof.
  intros p j E. destruct (Alph_110_111_111.cview_none_Alph_110_111_111 p j E) as (H1 & _).
  unfold Cc_1RB1LA_0LA1RC_0LA1RD_1LD0RB, cden, B0_1RB1LA_0LA1RC_0LA1RD_1LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
