(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall j, lift (cden [] [] j BB1_1RB1LA_0LA1RC_0LA1RD_1LD0RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LA1RC_0LA1RD_1LD0RB = (StA, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, ([S1;S1;S1]) ++ [S0]))).
  { unfold cden, BB1_1RB1LA_0LA1RC_0LA1RD_1LD0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, [S1;S1;S1]))).
  { unfold Cin_1RB1LA_0LA1RC_0LA1RD_1LD0RB. rewrite epow2_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_0LA1RC_0LA1RD_1LD0RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
Proof.
  intro j.
  destruct (Alph_110_111_1.cview_none_Alph_110_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_0LA1RC_0LA1RD_1LD0RB, cden, BE0_1RB1LA_0LA1RC_0LA1RD_1LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1LA_0LA1RC_0LA1RD_1LD0RB. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LA1RC_0LA1RD_1LD0RB p (pow2 j)).
  - exists (6 * j + 25), (cden [] [] j BB1_1RB1LA_0LA1RC_0LA1RD_1LD0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LA1RC_0LA1RD_1LD0RB j)].
    rewrite (gso_1RB1LA_0LA1RC_0LA1RD_1LD0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0LA1RD_1LD0RB B0_1RB1LA_0LA1RC_0LA1RD_1LD0RB BB1_1RB1LA_0LA1RC_0LA1RD_1LD0RB 6 25
             run_boot_1RB1LA_0LA1RC_0LA1RD_1LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 24), (cden [] [] j B1_1RB1LA_0LA1RC_0LA1RD_1LD0RB).
    split; [| exact (geo_1RB1LA_0LA1RC_0LA1RD_1LD0RB p j E)].
    rewrite (gxi_1RB1LA_0LA1RC_0LA1RD_1LD0RB j).
    exact (srun_sound tm true true che_1RB1LA_0LA1RC_0LA1RD_1LD0RB BE0_1RB1LA_0LA1RC_0LA1RD_1LD0RB B1_1RB1LA_0LA1RC_0LA1RD_1LD0RB 6 24
             run_exit_1RB1LA_0LA1RC_0LA1RD_1LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0LA1RC_0LA1RD_1LD0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0LA1RC_0LA1RD_1LD0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LA1RC_0LA1RD_1LD0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 30.
  assert (H : match csteps tm 30 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 30 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LA1RC_0LA1RD_1LD0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LA1RC_0LA1RD_1LD0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LA1RC_0LA1RD_1LD0RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LA1RC_0LA1RD_1LD0RB : forall t, ~ In t pins_1RB1LA_0LA1RC_0LA1RD_1LD0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB [] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB [SWin 1; SWinR 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB [SWin 1; SWinR 3; SCycL 3 0; SWin 8; SCycR 3; SWin 4; SWinR 8; SRotL 1; SWin 1; SWin 4] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB [SWin 1] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB [SWin 1; SWinR 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB [SWin 1; SWinR 3; SCycL 3 0; SWin 6] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB [SWin 1; SWinR 3; SCycL 3 0; SWin 8; SCycR 3; SWin 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_0LA1RC_0LA1RD_1LD0RB [SWin 1; SWinR 3; SCycL 3 0; SWin 7] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LA1RC_0LA1RD_1LD0RB : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LA1RC_0LA1RD_1LD0RB pins_1RB1LA_0LA1RC_0LA1RD_1LD0RB Cc 1).
  - exact boot_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
  - intros p _. apply lap_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
  - intros t Ht p _. apply fire_1RB1LA_0LA1RC_0LA1RD_1LD0RB. exact Ht.
Qed.

Theorem nonhalt_1RB1LA_0LA1RC_0LA1RD_1LD0RB : NonHalt tm_1RB1LA_0LA1RC_0LA1RD_1LD0RB.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1LA_0LA1RC_0LA1RD_1LD0RB. Qed.

