  split; [lia|]. split; [| exact (gei_1RB1LA_0LA1RC_0LA1RD_1RB0RB p j q0 E)].
  rewrite (gsi_1RB1LA_0LA1RC_0LA1RD_1RB0RB p j q0 E).
  exact (srun_sound tm false true chi_1RB1LA_0LA1RC_0LA1RD_1RB0RB A0_1RB1LA_0LA1RC_0LA1RD_1RB0RB A1_1RB1LA_0LA1RC_0LA1RD_1RB0RB 6 14
           run_int_1RB1LA_0LA1RC_0LA1RD_1RB0RB (Ap_Alph_110_111_111 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LA_0LA1RC_0LA1RD_1RB0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_0LA1RC_0LA1RD_1RB0RB.
