    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, [S1;S1;S1]))).
  { unfold Cin_1RB1LA_0LA1RC_0LA1RD_1RB0RB. rewrite epow2_1RB1LA_0LA1RC_0LA1RD_1RB0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
