Lemma run_inner_1RB1LA_0LA1RC_0LC0RD_0LA1RC : srun tm false true chn_1RB1LA_0LA1RC_0LC0RD_0LA1RC AI0_1RB1LA_0LA1RC_0LC0RD_0LA1RC = Some (AI1_1RB1LA_0LA1RC_0LC0RD_0LA1RC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_0LA1RC_0LC0RD_0LA1RC : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_1RB1LA_0LA1RC_0LC0RD_0LA1RC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_1RB1LA_0LA1RC_0LC0RD_0LA1RC : srun tm true true chb_1RB1LA_0LA1RC_0LC0RD_0LA1RC B0_1RB1LA_0LA1RC_0LC0RD_0LA1RC = Some (BB1_1RB1LA_0LA1RC_0LC0RD_0LA1RC, 4, 7).
