      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0LA1RC_0LC1RD_0LA0RB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
