Definition mk_1RB1LA_0LA1RC_0LC1RD_0LD0RB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1LA_0LA1RC_0LC1RD_0LD0RB.

(** 1RB1LA_0LA1RC_0LC1RD_0LD0RB *)
Definition tm_1RB1LA_0LA1RC_0LC1RD_0LD0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S0 DL StA | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S0 DL StC | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S0 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LA_0LA1RC_0LC1RD_0LD0RB : list Instr := [].
Definition tmw_1RB1LA_0LA1RC_0LC1RD_0LD0RB : TM := tm_wrap_trs tm_1RB1LA_0LA1RC_0LC1RD_0LD0RB pins_1RB1LA_0LA1RC_0LC1RD_0LD0RB.
Local Notation tm := tmw_1RB1LA_0LA1RC_0LC1RD_0LD0RB.

Definition Cc_1RB1LA_0LA1RC_0LC1RD_0LD0RB (p : positive) : cconf := (StB, (Ap_Alph_011_111_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1LA_0LA1RC_0LC1RD_0LD0RB.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StB (mkS [S0;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StB (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB1LA_0LA1RC_0LC1RD_0LD0RB : list lstep := [SWin 2].

Lemma run_z_1RB1LA_0LA1RC_0LC1RD_0LD0RB : srun tm false true chz_1RB1LA_0LA1RC_0LC1RD_0LD0RB Z0_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Some (Z1_1RB1LA_0LA1RC_0LC1RD_0LD0RB, 0, 2).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StB (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StB (mkS [S0;S1;S1] [S0;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_1RB1LA_0LA1RC_0LC1RD_0LD0RB : list lstep := [SWin 3; SCycL 3 0; SWin 2; SCycR 3; SWin 3].

Lemma run_p_1RB1LA_0LA1RC_0LC1RD_0LD0RB : srun tm false true chp_1RB1LA_0LA1RC_0LC1RD_0LD0RB P0_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Some (P1_1RB1LA_0LA1RC_0LC1RD_0LD0RB, 6, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StB (mkS [] [S0;S1;S1] 1 1 [S1]) S0 (mkS [] [] 0 0 []).
(** ** The FIRST INNER anchor family -- Ap_Alph_101_111_1 at StC *)
Definition Cin_1RB1LA_0LA1RC_0LC1RD_0LD0RB (v : positive) : cconf := (StC, (Ap_Alph_101_111_1 v ++ [S1], S0, [])).
Local Notation Cin := Cin_1RB1LA_0LA1RC_0LC1RD_0LD0RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall n, Ap_Alph_101_111_1 (pow2 n) = rep [S1;S0;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB1LA_0LA1RC_0LC1RD_0LD0RB : list lstep := [SRotL 1; SWin 7; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner_1RB1LA_0LA1RC_0LC1RD_0LD0RB : srun tm false true chn_1RB1LA_0LA1RC_0LC1RD_0LD0RB AI0_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Some (AI1_1RB1LA_0LA1RC_0LC1RD_0LD0RB, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** ** The SECOND INNER anchor family -- Ap_Alph_110_111_1 at StD *)
Definition Cin2_1RB1LA_0LA1RC_0LC1RD_0LD0RB (v : positive) : cconf := (StD, (Ap_Alph_110_111_1 v ++ [S1;S1], S0, [])).
Local Notation Cin2 := Cin2_1RB1LA_0LA1RC_0LC1RD_0LD0RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow22_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall n, Ap_Alph_110_111_1 (pow2 n) = rep [S1;S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI20_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI21_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StD (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn2_1RB1LA_0LA1RC_0LC1RD_0LD0RB : list lstep := [SRotL 1; SWin 5; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner2_1RB1LA_0LA1RC_0LC1RD_0LD0RB : srun tm false true chn2_1RB1LA_0LA1RC_0LC1RD_0LD0RB AI20_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Some (AI21_1RB1LA_0LA1RC_0LC1RD_0LD0RB, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1LA_0LA1RC_0LC1RD_0LD0RB : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_boot_1RB1LA_0LA1RC_0LC1RD_0LD0RB : srun tm true true chb_1RB1LA_0LA1RC_0LC1RD_0LD0RB B0_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Some (BB1_1RB1LA_0LA1RC_0LC1RD_0LD0RB, 6, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** shift: count 1's all-ones fill -> count 2's anchor.
    WAVE18 section 4c -- "count 8->15, shift, count 8->15 again". *)
Definition BM0_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition BM1_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StD (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chm_1RB1LA_0LA1RC_0LC1RD_0LD0RB : list lstep := [SRotL 1; SWin 7; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_shift_1RB1LA_0LA1RC_0LC1RD_0LD0RB : srun tm true true chm_1RB1LA_0LA1RC_0LC1RD_0LD0RB BM0_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Some (BM1_1RB1LA_0LA1RC_0LC1RD_0LD0RB, 6, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_0LA1RC_0LC1RD_0LD0RB : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LA_0LA1RC_0LC1RD_0LD0RB : list lstep := [SRotL 1; SWin 5; SCycL 3 0; SWin 2; SWinL 4; SCycR 3; SWin 1; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1LA_0LA1RC_0LC1RD_0LD0RB : srun tm true true che_1RB1LA_0LA1RC_0LC1RD_0LD0RB BE0_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Some (B1_1RB1LA_0LA1RC_0LC1RD_0LD0RB, 6, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_1RB1LA_0LA1RC_0LC1RD_0LD0RB /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_0LA1RC_0LC1RD_0LD0RB, cden, Z0_1RB1LA_0LA1RC_0LC1RD_0LD0RB, Z1_1RB1LA_0LA1RC_0LC1RD_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_1RB1LA_0LA1RC_0LC1RD_0LD0RB /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_1RB1LA_0LA1RC_0LC1RD_0LD0RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1LA_0LA1RC_0LC1RD_0LD0RB, cden, P0_1RB1LA_0LA1RC_0LC1RD_0LD0RB, P1_1RB1LA_0LA1RC_0LC1RD_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LA_0LA1RC_0LC1RD_0LD0RB p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LA_0LA1RC_0LC1RD_0LD0RB Z0_1RB1LA_0LA1RC_0LC1RD_0LD0RB Z1_1RB1LA_0LA1RC_0LC1RD_0LD0RB 0 2
               run_z_1RB1LA_0LA1RC_0LC1RD_0LD0RB (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LA_0LA1RC_0LC1RD_0LD0RB p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_0LA1RC_0LC1RD_0LD0RB P0_1RB1LA_0LA1RC_0LC1RD_0LD0RB P1_1RB1LA_0LA1RC_0LC1RD_0LD0RB 6 8
               run_p_1RB1LA_0LA1RC_0LC1RD_0LD0RB (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_0LA1RC_0LC1RD_0LD0RB.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_1RB1LA_0LA1RC_0LC1RD_0LD0RB, cden, B0_1RB1LA_0LA1RC_0LC1RD_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LA1RC_0LC1RD_0LD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_0LA1RC_0LC1RD_0LD0RB
             = (StB, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_1RB1LA_0LA1RC_0LC1RD_0LD0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LA_0LA1RC_0LC1RD_0LD0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LA_0LA1RC_0LC1RD_0LD0RB. reflexivity.
Qed.

Lemma gsn_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI0_1RB1LA_0LA1RC_0LC1RD_0LD0RB.
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (H1 & _).
  unfold Cin_1RB1LA_0LA1RC_0LC1RD_0LD0RB, cden, AI0_1RB1LA_0LA1RC_0LC1RD_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_1RB1LA_0LA1RC_0LC1RD_0LD0RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (_ & H2).
  unfold Cin_1RB1LA_0LA1RC_0LC1RD_0LD0RB, cden, AI1_1RB1LA_0LA1RC_0LC1RD_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 10), (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_1RB1LA_0LA1RC_0LC1RD_0LD0RB).
  split; [lia|]. split; [| exact (gen_1RB1LA_0LA1RC_0LC1RD_0LD0RB v i q0 E)].
  rewrite (gsn_1RB1LA_0LA1RC_0LC1RD_0LD0RB v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_0LA1RC_0LC1RD_0LD0RB AI0_1RB1LA_0LA1RC_0LC1RD_0LD0RB AI1_1RB1LA_0LA1RC_0LC1RD_0LD0RB 6 10
           run_inner_1RB1LA_0LA1RC_0LC1RD_0LD0RB (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall j, lift (cden [] [] j BB1_1RB1LA_0LA1RC_0LC1RD_0LD0RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LA1RC_0LC1RD_0LD0RB = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_1RB1LA_0LA1RC_0LC1RD_0LD0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LA_0LA1RC_0LC1RD_0LD0RB. rewrite epow2_1RB1LA_0LA1RC_0LC1RD_0LD0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LA_0LA1RC_0LC1RD_0LD0RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_1RB1LA_0LA1RC_0LC1RD_0LD0RB.
Proof.
  intro j.
  destruct (Alph_101_111_1.cview_none_Alph_101_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_0LA1RC_0LC1RD_0LD0RB, cden, BM0_1RB1LA_0LA1RC_0LC1RD_0LD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

Lemma gsn2_1RB1LA_0LA1RC_0LC1RD_0LD0RB : forall v i q0, cview v = (i, Some q0) ->
  Cin2 v = cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI20_1RB1LA_0LA1RC_0LC1RD_0LD0RB.
Proof.
