    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LA1RC_0LD0RB_0RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LA1RC_0LD0RB_0RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
