Lemma lapi_1RB1LA_0LA1RC_0LD0RB_1LA0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1LA_0LA1RC_0LD0RB_1LA0RC p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LA_0LA1RC_0LD0RB_1LA0RC Z0_1RB1LA_0LA1RC_0LD0RB_1LA0RC Z1_1RB1LA_0LA1RC_0LD0RB_1LA0RC 0 6
               run_z_1RB1LA_0LA1RC_0LD0RB_1LA0RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LA_0LA1RC_0LD0RB_1LA0RC p j' q0 E) as (HA & HB).
    exists (4 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_0LA1RC_0LD0RB_1LA0RC P0_1RB1LA_0LA1RC_0LD0RB_1LA0RC P1_1RB1LA_0LA1RC_0LD0RB_1LA0RC 4 10
               run_p_1RB1LA_0LA1RC_0LD0RB_1LA0RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
