      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LA_0LA1RC_0LD0RB_1LA0RC : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_0LD0RB_1LA0RC.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LA1RC_0LD0RB_1LA0RC pins_1RB1LA_0LA1RC_0LD0RB_1LA0RC Cc 1).
