Lemma fire_1RB1LA_0LA1RC_0LD0RB_1RA1LD : forall t, ~ In t pins_1RB1LA_0LA1RC_0LD0RB_1RA1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
