Lemma gen_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_0LA1RC_0LD0RB_1RB0RC) = lift (Cin (Pos.succ v)).
