(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LA_0LA1RC_0LD0RB_1RB0RC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LA_0LA1RC_0LD0RB_1RB0RC, cden, BE0_1RB1LA_0LA1RC_0LD0RB_1RB0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LA1RC_0LD0RB_1RB0RC p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_1RB1LA_0LA1RC_0LD0RB_1RB0RC).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LA1RC_0LD0RB_1RB0RC j)].
    rewrite (gso_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LA1RC_0LD0RB_1RB0RC B0_1RB1LA_0LA1RC_0LD0RB_1RB0RC BB1_1RB1LA_0LA1RC_0LD0RB_1RB0RC 4 7
             run_boot_1RB1LA_0LA1RC_0LD0RB_1RB0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 13), (cden [] [] j B1_1RB1LA_0LA1RC_0LD0RB_1RB0RC).
    split; [| exact (geo_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j E)].
    rewrite (gxi_1RB1LA_0LA1RC_0LD0RB_1RB0RC j).
    exact (srun_sound tm true true che_1RB1LA_0LA1RC_0LD0RB_1RB0RC BE0_1RB1LA_0LA1RC_0LD0RB_1RB0RC B1_1RB1LA_0LA1RC_0LD0RB_1RB0RC 4 13
             run_exit_1RB1LA_0LA1RC_0LD0RB_1RB0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LA_0LA1RC_0LD0RB_1RB0RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 9 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_0LA1RC_0LD0RB_1RB0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j E)].
Qed.

(** A state that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.vis_via_int_lift] carries it to every anchor. *)
Lemma visi_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LA_0LA1RC_0LD0RB_1RB0RC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j q0 E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LA_0LA1RC_0LD0RB_1RB0RC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LA_0LA1RC_0LD0RB_1RB0RC p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LA1RC_0LD0RB_1RB0RC : forall t, ~ In t pins_1RB1LA_0LA1RC_0LD0RB_1RB0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0LA1RC_0LD0RB_1RB0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_0LA1RC_0LD0RB_1RB0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0LA1RC_0LD0RB_1RB0RC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_0LA1RC_0LD0RB_1RB0RC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_0LA1RC_0LD0RB_1RB0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* C0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LA_0LA1RC_0LD0RB_1RB0RC (StC, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LA_0LA1RC_0LD0RB_1RB0RC [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0LA1RC_0LD0RB_1RB0RC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LA_0LA1RC_0LD0RB_1RB0RC (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LA_0LA1RC_0LD0RB_1RB0RC [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 4] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LA_0LA1RC_0LD0RB_1RB0RC (StD, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LA_0LA1RC_0LD0RB_1RB0RC [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LA1RC_0LD0RB_1RB0RC : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_0LD0RB_1RB0RC.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LA1RC_0LD0RB_1RB0RC pins_1RB1LA_0LA1RC_0LD0RB_1RB0RC Cc 1).
  - exact boot_1RB1LA_0LA1RC_0LD0RB_1RB0RC.
  - intros p _. apply lap_1RB1LA_0LA1RC_0LD0RB_1RB0RC.
  - intros t Ht p _. apply fire_1RB1LA_0LA1RC_0LD0RB_1RB0RC. exact Ht.
Qed.

Theorem nonhalt_1RB1LA_0LA1RC_0LD0RB_1RB0RC : NonHalt tm_1RB1LA_0LA1RC_0LD0RB_1RB0RC.
