Lemma geo_1RB1LA_0LA1RC_0LD0RB_1RB1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_0LA1RC_0LD0RB_1RB1LD) = lift (Cc (Pos.succ p)).
