  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_0LA1RC_0LD0RB_1RB1LD = (StA, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1LA_0LA1RC_0LD0RB_1RB1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
