  unfold Cin_1RB1LA_0LA1RC_0LD0RB____0RB, cden, BE0_1RB1LA_0LA1RC_0LD0RB____0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
