    exact (srun_sound tm true true che_1RB1LA_0LA1RC_0LD0RB____0RB BE0_1RB1LA_0LA1RC_0LD0RB____0RB B1_1RB1LA_0LA1RC_0LD0RB____0RB 4 13
             run_exit_1RB1LA_0LA1RC_0LD0RB____0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LA_0LA1RC_0LD0RB____0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
