(** ** Bootstrap *)

Lemma boot_1RB1LA_0LA1RC_0LD0RB____0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
