  apply (fire_of_run_instr tm Cc false true l A0_1RB1LA_0LA1RC_0LD0RB____0RB p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LA_0LA1RC_0LD0RB____0RB p j q0 E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1LA_0LA1RC_0LD0RB____0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LA_0LA1RC_0LD0RB____0RB = Some t ->
