(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_0LA1RC_0LD0RB____0RB : forall t, ~ In t pins_1RB1LA_0LA1RC_0LD0RB____0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_0LA1RC_0LD0RB____0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_0LA1RC_0LD0RB____0RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0LA1RC_0LD0RB____0RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LA_0LA1RC_0LD0RB____0RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_0LA1RC_0LD0RB____0RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
    vm_compute; reflexivity.
  - (* C0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LA_0LA1RC_0LD0RB____0RB (StC, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LA_0LA1RC_0LD0RB____0RB [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_0LA1RC_0LD0RB____0RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LA_0LA1RC_0LD0RB____0RB (StD, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LA_0LA1RC_0LD0RB____0RB [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
Qed.

Theorem nqhtr_1RB1LA_0LA1RC_0LD0RB____0RB : NeverQuasiHaltsTr tm_1RB1LA_0LA1RC_0LD0RB____0RB.
Proof.
  apply (glue_neverqhtr tm_1RB1LA_0LA1RC_0LD0RB____0RB pins_1RB1LA_0LA1RC_0LD0RB____0RB Cc 1).
  - exact boot_1RB1LA_0LA1RC_0LD0RB____0RB.
  - intros p _. apply lap_1RB1LA_0LA1RC_0LD0RB____0RB.
  - intros t Ht p _. apply fire_1RB1LA_0LA1RC_0LD0RB____0RB. exact Ht.
Qed.

Theorem nonhalt_1RB1LA_0LA1RC_0LD0RB____0RB : NonHalt tm_1RB1LA_0LA1RC_0LD0RB____0RB.
