Lemma gsn_1RB1LA_0LA1RC_0LD0RB____1RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB1LA_0LA1RC_0LD0RB____1RB.
