(** ** The lap *)

Lemma lap_1RB1LA_0LA1RC_0LD0RB____1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
